export interface NodeLike {
  tag: string;
}

export function makeNode(factory: (tag: string) => unknown): NodeLike {
  const node = factory("section");
  if (typeof node !== "object" || node === null || typeof (node as { tag?: unknown }).tag !== "string") {
    throw new TypeError("factory returned non-node");
  }
  return node as NodeLike;
}

