import { makeNode } from "./solution";
import type { NodeLike } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function rejects(valueFactory: () => unknown, message: string): void {
  let error: unknown;
  try { makeNode(valueFactory); } catch (caught) { error = caught; }
  assert(error instanceof TypeError && error.message === "factory returned non-node", message);
}

let calls = 0;
const original = { tag: "section", extra: 42 };
const result: NodeLike = makeNode(tag => {
  calls += 1;
  assert(tag === "section", "factory receives section");
  return original;
});
assert(calls === 1, "factory called exactly once");
assert(result === original, "exact factory object is returned");
assert((result as { extra?: number }).extra === 42, "extra properties are retained");

const emptyTag = { tag: "" };
assert(makeNode(() => emptyTag) === emptyTag, "empty string tag is valid");
for (const invalid of [undefined, null, 3, "section", {}, { tag: 1 }, { tag: null }]) {
  let invalidCalls = 0;
  rejects(() => { invalidCalls += 1; return invalid; }, "invalid node rejected");
  assert(invalidCalls === 1, "invalid factory still called exactly once");
}

